    public static void apply() {
        for (int i = 0; i < KEYS.length; i++) {
            try {
                Field f = org.telegram.ui.ActionBar.Theme.class.getField(KEYS[i]);
                f.setInt(null, VALUES[i]);
            } catch (Throwable ignore) {}
        }
        if (org.telegram.spectra.SpectraConfig.isPureAmoled()) {
            applyAmoled();
        }
        if (!org.telegram.spectra.SpectraConfig.isHideDividers()) {
            // keep native divider look
        }
        try {
            int unread = org.telegram.spectra.SpectraConfig.isCustomUnreadColor()
                    ? org.telegram.spectra.SpectraConfig.getUnreadColor() : 0xFF2CE876;
            Field f1 = org.telegram.ui.ActionBar.Theme.class.getField("key_chats_unreadCounter");
            f1.setInt(null, unread);
        } catch (Throwable ignore) {}
    }

    private static void applyAmoled() {
        replace("key_windowBackgroundWhite", 0xFF000000);
        replace("key_windowBackgroundGray", 0xFF000000);
        replace("key_chat_wallpaper", 0xFF000000);
        replace("key_dialogBackground", 0xFF0A0F0C);
        replace("key_sheet_other", 0xFF0A0F0C);
        replace("key_actionBarDefault", 0xFF050706);
        replace("key_chat_messagePanelBackground", 0xFF0A0F0C);
    }

    private static void replace(String key, int value) {
        try {
            Field f = org.telegram.ui.ActionBar.Theme.class.getField(key);
            f.setInt(null, value);
        } catch (Throwable ignore) {}
    }

